type Strategy interface {
	// Backoff returns the amount of time to wait before the next retry given
	// the number of consecutive failures.
	Backoff(retries int) time.Duration
}

const (
	// baseDelay is the amount of time to wait before retrying after the first
	// failure.
	defaultBaseDelay = 1.0 * time.Second
	// factor is applied to the backoff after each retry.
	defaultFactor = 1.6
	// jitter provides a range to randomize backoff delays.
	defaultJitter = 0.2
)

// Exponential implements exponential backoff algorithm as defined in
// https://github.com/grpc/grpc/blob/master/doc/connection-backoff.md.
type Exponential struct {
	// BaseDelay is the amount of time to wait before retrying after the first
	// failure. A zero value uses the default value.
	BaseDelay time.Duration
	// Multiplier is the factor by which the backoff increases after each
	// failed retry. A zero value uses the default value.
	Multiplier float64
	// Jitter is the factor by which backoff delays are randomized. A zero value
	// uses the default value.
	Jitter float64
	// MaxDelay is the upper bound of backoff delay.
	MaxDelay time.Duration
}

// Backoff returns the amount of time to wait before the next retry given the
// number of retries.
func (bc Exponential) Backoff(retries int) time.Duration {
	baseDelay := bc.BaseDelay
	if baseDelay == 0 {
		baseDelay = defaultBaseDelay
	}
	factor := bc.Multiplier
	if factor == 0 {
		factor = defaultFactor
	}
	jitter := bc.Jitter
	if jitter == 0 {
		jitter = defaultJitter
	}
	if retries == 0 {
		return baseDelay
	}
	backoff, max := float64(baseDelay), float64(bc.MaxDelay)
	for backoff < max && retries > 0 {
		backoff *= factor
		retries--
	}
	if backoff > max {
		backoff = max
	}
	// Randomize backoff delays so that if a cluster of requests start at
	// the same time, they won't operate in lockstep.
	backoff *= 1 + jitter*(grpcrand.Float64()*2-1)
	if backoff < 0 {
		return 0
	}
	return time.Duration(backoff)
}

